/**
 * Is the repository at the schema this deployment runs?
 *
 * A deployment committing to a remote repository (a built bundle) plans every
 * change against the collections it *serves*, and renders the commit's
 * generated schema files from those. The collection source it edits is fetched
 * fresh from the repository. The two agree only while the repository holds no
 * schema change this deployment is not running yet. When it does — a change
 * committed here and not deployed, or one a developer pushed — the next commit
 * would rewrite the generated files from the served collections and leave that
 * change out of them.
 *
 * This used to be a flag in process memory, set when this process committed.
 * A restart, a second replica, or a developer's push got past it. The check
 * here keeps no state: render the generated files from the collections this
 * deployment serves and compare them with the repository's copies. Equal means
 * the repository's schema is the one running here; different means something
 * is committed that is not running yet, and the change is refused.
 *
 * Why this and not a commit SHA. Comparing the branch head with the commit the
 * bundle was built from would be exact, but no bundle records that commit
 * today, and the head read at boot is no substitute: after a restart that
 * follows an undeployed commit, that head *is* the undeployed commit. The
 * generated files are what a change here rewrites, so they are what has to
 * agree.
 *
 * The comparison tolerates line endings and trailing whitespace only. A file
 * written by another Rebase version, or reformatted, also differs, and the
 * refusal says how to bring it back in step.
 */
import type { SchemaChangeFile } from "@rebasepro/types";
import type { SchemaEditRepository } from "./apply-schema-change";

export class RepositoryAheadOfDeploymentError extends Error {
    constructor(readonly paths: string[], branch: string) {
        super(
            `The repository's ${paths.join(", ")} ${paths.length === 1 ? "is" : "are"} not what the collections ` +
            "this deployment runs generate, so a schema change is committed that this deployment is not running " +
            `yet: one made here, or one pushed to ${branch}. Deploy it, then make the next change. Until then a ` +
            "change here is planned against the collections this deployment runs, and its commit would rewrite " +
            `${paths.length === 1 ? "that file" : "those files"} without the change waiting to deploy. ` +
            "If nothing is waiting to deploy, the file was generated by another Rebase version, reformatted, or " +
            "edited by hand: run `rebase schema generate` with the version this deployment runs, commit the " +
            "result and deploy it. Nothing was changed."
        );
        this.name = "RepositoryAheadOfDeploymentError";
    }
}

/** Line endings and trailing whitespace are not schema. */
const normalize = (contents: string): string =>
    contents.replace(/\r\n?/g, "\n").split("\n").map(line => line.trimEnd()).join("\n").trimEnd();

/**
 * Refuse when the repository's generated files differ from `served`, the files
 * the collections this deployment serves generate.
 *
 * A file the repository does not have is not a difference: nothing has
 * committed one, so there is no change in it for a commit to leave out. A
 * repository that cannot read a file cannot be checked, and is refused: the
 * remote write path reads every file it edits, so that repository could not
 * make the change either.
 */
export async function refuseWhenRepositoryIsAhead(
    repository: Pick<SchemaEditRepository, "readFile" | "currentBranch">,
    served: SchemaChangeFile[]
): Promise<void> {
    if (!repository.readFile) {
        throw new Error(
            "This repository cannot read a file, so whether it holds a change this deployment is not running " +
            "yet cannot be checked. Nothing was changed."
        );
    }
    const differing: string[] = [];
    for (const file of served) {
        if (file.deleted) continue;
        const committed = await repository.readFile(file.path);
        if (committed === undefined) continue;
        if (normalize(committed) !== normalize(file.contents)) differing.push(file.path);
    }
    if (differing.length > 0) {
        throw new RepositoryAheadOfDeploymentError(differing, await repository.currentBranch());
    }
}
